def count_divisors(n):
    """Calculates the total number of positive divisors, tau(n)."""
    if n <= 0:
        return 0
    count = 0
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
    return count

def d(n):
    """Calculates the number of positive divisors other than 1 and itself."""
    if n <= 0:
        return -1 # Should not happen based on constraints
    tau_n = count_divisors(n)
    # d(n) = tau(n) - 2. Since d(n) must be non-negative, 
    # if tau(n) is 1 or 2 (n=1 or n=prime), d(n) is 0.
    return max(0, tau_n - 2)

N_LIMIT = 1000
OFFSET = 735

results = []
min_a = float('inf')
found_solution = False

print(f"Searching for minimum a where d(n) = d(n+735) = a for n in [1, {N_LIMIT}]")

for n in range(1, N_LIMIT + 1):
    d_n = d(n)
    d_n_plus_735 = d(n + OFFSET)

    if d_n == d_n_plus_735:
        a = d_n
        results.append((n, a))

        if a < min_a:
            min_a = a
            found_solution = True

if found_solution:
    print(f"\nMinimum 'a' found: {min_a}")
    print("Pairs (n, a) found (first 10 shown):")
    for n_val, a_val in results[:10]:
        print(f"n={n_val}, a={a_val}")
else:
    print("\nNo matching pairs found in the search range.")
